// ---------------------------------------------------------------------------
// Solar Dial — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'
import * as zosFs from '@zos/fs'
import * as SolarSensors from '@zos/sensor'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_k6gj = [
  A('clock-0.png'),
  A('clock-1.png'),
  A('clock-2.png'),
  A('clock-3.png'),
  A('clock-4.png'),
  A('clock-5.png'),
  A('clock-6.png'),
  A('clock-7.png'),
  A('clock-8.png'),
  A('clock-9.png'),
]

const img_Minute_AOD_27kp = [
  A('aod-0.png'),
  A('aod-1.png'),
  A('aod-2.png'),
  A('aod-3.png'),
  A('aod-4.png'),
  A('aod-5.png'),
  A('aod-6.png'),
  A('aod-7.png'),
  A('aod-8.png'),
  A('aod-9.png'),
]

const img_Weekday_645p = [
  A('week_w1.png'),
  A('weekday-tue.png'),
  A('week_w3.png'),
  A('week_w4.png'),
  A('week_w5.png'),
  A('week_w6.png'),
  A('week_w7.png'),
]

const img_Day_t7mt = [
  A('font_1_0.png'),
  A('date-1.png'),
  A('date-2.png'),
  A('font_1_3.png'),
  A('font_1_4.png'),
  A('font_1_5.png'),
  A('font_1_6.png'),
  A('font_1_7.png'),
  A('font_1_8.png'),
  A('font_1_9.png'),
]

const img_Sunrise_e1jp = [
  A('solar-time-0.png'),
  A('solar-time-1.png'),
  A('solar-time-2.png'),
  A('solar-time-3.png'),
  A('solar-time-4.png'),
  A('solar-time-5.png'),
  A('solar-time-6.png'),
  A('solar-time-7.png'),
  A('solar-time-8.png'),
  A('solar-time-9.png'),
]

// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    variantIdx = dcGet('dialcraft_variant')

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Solar sky (IMG)
    const variants_0 = [A('solar-dial.png'), A('sky-horizon.png'), A('sky-nautical.png'), A('sky-astronomical.png'), A('sky-night.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.solarSky = variant_0
    F.solarSky = variants_0

    // Sun and moon marker (IMG)
    const variants_1 = [A('sun.png'), A('moon.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(298),
      y: px(106),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.solarMarker = variant_1
    F.solarMarker = variants_1

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(199),
      minute_startY: px(176),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_k6gj,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(181),
      y: px(176),
      src: A('clock-colon.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(84),
      hour_startY: px(176),
      hour_zero: 1,
      hour_space: px(-4),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_k6gj,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(199),
      minute_startY: px(192),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_AOD_27kp,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon AOD (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(181),
      y: px(192),
      src: A('aod-colon.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(84),
      hour_startY: px(192),
      hour_zero: 1,
      hour_space: px(-4),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_AOD_27kp,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(133),
      y: px(126),
      week_en: img_Weekday_645p,
      week_sc: img_Weekday_645p,
      week_tc: img_Weekday_645p,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(208),
      day_startY: px(126),
      day_zero: 0,
      day_space: px(-4),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_t7mt,
      day_sc_array: img_Day_t7mt,
      day_tc_array: img_Day_t7mt,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Sunrise icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(38),
      y: px(360),
      src: A('sunrise.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Sunrise (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(27),
      y: px(394),
      w: px(78),
      type: ui.data_type.SUN_RISE,
      font_array: img_Sunrise_e1jp,
      h_space: px(1),
      padding: true,
      align_h: ui.align.LEFT,
      invalid_image: A('solar-time-missing.png'),
      dot_image: A('solar-time-colon.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Sunset icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(312),
      y: px(360),
      src: A('sunset.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Sunset (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(301),
      y: px(394),
      w: px(78),
      type: ui.data_type.SUN_SET,
      font_array: img_Sunrise_e1jp,
      h_space: px(1),
      padding: true,
      align_h: ui.align.LEFT,
      invalid_image: A('solar-time-missing.png'),
      dot_image: A('solar-time-colon.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      dcSet('dialcraft_variant', variantIdx)
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    {
    function solarDialState(minute, rise, set) {
      if (!Number.isFinite(rise) || !Number.isFinite(set) || rise < 0 || set >= 1440 || set <= rise) {
        rise = 360;
        set = 1080;
      }
      const daylight = set - rise;
      const noon = (rise + set) / 2;
      const wrap = (m) => ((m % 1440) + 1440) % 1440;
      const sinceRise = wrap(minute - rise);
      const day = sinceRise < daylight;
      const fromHorizon = day ? Math.min(sinceRise, daylight - sinceRise) :
        Math.min(sinceRise - daylight, 1440 - sinceRise);
      // Zepp tide data gives the two horizon crossings. These three markers are estimated.
      const twilight = [30, 60, 90].filter((offset) => offset < (1440 - daylight) / 2);
      const sky = day ? (fromHorizon < 30 ? 1 : 0) :
        fromHorizon < 30 ? 1 : fromHorizon < 60 ? 2 : fromHorizon < 90 ? 3 : 4;
      const angleAt = (m) => (m - noon) / 4;
      return {
        angle: angleAt(minute),
        day,
        sky,
        sunrise: angleAt(rise),
        sunset: angleAt(set),
        twilight: twilight.flatMap((offset) => [angleAt(rise - offset), angleAt(set + offset)]),
      };
    }
    function solarDialPoint(dial, angle, radius = dial.radius) {
      const radians = angle * Math.PI / 180;
      return {
        x: dial.centerX + radius * Math.sin(radians),
        y: dial.centerY - radius * Math.cos(radians),
      };
    }
    const DIAL = { centerX: 195, centerY: 218.5, radius: 158, trackRadius: 175 };
    const MARKER_SIZE = 69;

    function markerAt(angle) {
      const point = solarDialPoint(DIAL, angle);
      return { x: Math.round(point.x - MARKER_SIZE / 2), y: Math.round(point.y - MARKER_SIZE / 2) };
    }

    function solarTimes(weather) {
      if (!weather) return [360, 1080];
      // Firmware versions expose either method name.
      for (const method of ['getForecastWeather', 'getForecast']) {
        try {
          if (typeof weather[method] !== 'function') continue;
          const forecast = weather[method]();
          const today = forecast && forecast.tideData && forecast.tideData.data && forecast.tideData.data[0];
          if (!today) continue;
          const rise = toMinutes(today.sunrise);
          const set = toMinutes(today.sunset);
          if (rise >= 0 && set > rise) return [rise, set];
        } catch (error) { /* Try the alternate method or use the default daylight interval. */ }
      }
      return [360, 1080];
    }

    function toMinutes(time) {
      if (!time || !Number.isInteger(time.hour) || !Number.isInteger(time.minute) ||
          time.hour < 0 || time.hour > 23 || time.minute < 0 || time.minute > 59) return -1;
      return time.hour * 60 + time.minute;
    }

    const time = new SolarSensors.Time();
    let weather;
    try {
      if (SolarSensors.Weather) weather = new SolarSensors.Weather();
    } catch (error) { /* Weather is optional. */ }

    const normal = ui.show_level.ONLY_NORMAL;
    const twilightColors = [0xdfaa81, 0xb594c7, 0x8299d3];
    const track = [];
    let lastMarker;
    let lastSky;
    let lastTide;

    function drawTrack(state) {
      track.forEach((widget) => ui.deleteWidget(widget));
      track.length = 0;
      const radius = DIAL.trackRadius;
      const arc = (start, end, color) => {
        if (end <= start) return;
        track.push(ui.createWidget(ui.widget.ARC, {
          x: pxv(DIAL.centerX - radius), y: pxv(DIAL.centerY - radius),
          w: pxv(radius * 2), h: pxv(radius * 2), radius: pxv(radius),
          start_angle: start, end_angle: end, line_width: pxv(2), color, show_level: normal,
        }));
      };
      arc(0, 359.99, 0x536d9d);
      const start = (state.sunrise + 270) % 360;
      const end = start + state.sunset - state.sunrise;
      arc(start, Math.min(end, 360), 0xf6be59);
      if (end > 360) arc(0, end - 360, 0xf6be59);
      state.twilight.forEach((angle, index) => {
        const point = solarDialPoint(DIAL, angle, radius - 8);
        track.push(ui.createWidget(ui.widget.CIRCLE, {
          center_x: pxv(point.x), center_y: pxv(point.y), radius: pxv(2),
          color: twilightColors[Math.floor(index / 2)], show_level: normal,
        }));
      });
    }

    function update() {
      const minute = time.getHours() * 60 + time.getMinutes();
      const [rise, set] = solarTimes(weather);
      const state = solarDialState(minute, rise, set);
      const marker = markerAt(state.angle);
      if (lastSky !== state.sky) {
        W.solarSky.setProperty(ui.prop.SRC, F.solarSky[state.sky]);
        lastSky = state.sky;
      }
      if (!lastMarker || marker.x !== lastMarker.x || marker.y !== lastMarker.y || state.day !== lastMarker.day) {
        W.solarMarker.setProperty(ui.prop.MORE, {
          x: pxv(marker.x), y: pxv(marker.y), src: F.solarMarker[state.day ? 0 : 1],
        });
        lastMarker = { ...marker, day: state.day };
      }
      const tide = rise * 1440 + set;
      if (lastTide !== tide) {
        lastTide = tide;
        drawTrack(state);
      }
    }

    update();
    time.onPerMinute(update);
    ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: update });

    }

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
